#requires -Version 5.1
<#
Updater fakultas/prodi untuk OSDJ-LPPM 1.6 -> 1.6.2-journal-unit.
Penggunaan: .\Update-Fakultas-Prodi.ps1 -ProjectPath "D:\project\OSDJ-LPPM"
Pemeriksaan tanpa perubahan: tambahkan -CheckOnly.
Gunakan PHP host yang sama dengan aplikasi (XAMPP/Laragon/php artisan serve).
Untuk Docker, updater host ini tidak menjalankan perintah di container.
Backup database sendiri sebelum pemasangan. Script membuat backup SOURCE privat,
tidak menyalin .env, mengganti APP_KEY, mengunduh dependency, atau mereset database.
Jika source yang ditargetkan pernah dimodifikasi, script berhenti tanpa menimpanya.
Asal jurnal disimpan pada karya publikasi, terpisah dari afiliasi penulis.
Fakultas dan prodi hanya dari Data Referensi. Tidak membuat master baru.
#>
[CmdletBinding()]
param(
 [Parameter(Mandatory=$true)][string]$ProjectPath,
 [string]$Php = 'php',
 [switch]$CheckOnly
)
$ErrorActionPreference = 'Stop'
$runtime = (Get-Command $Php -CommandType Application -ErrorAction Stop).Source
$project = (Resolve-Path -LiteralPath $ProjectPath -ErrorAction Stop).Path
$temp = [System.IO.Path]::GetTempFileName()
try {
 $bytes = [Convert]::FromBase64String('')
 [System.IO.File]::WriteAllBytes($temp, $bytes)
 $mode = if ($CheckOnly) { 'check' } else { 'install' }
 & $runtime $temp $project $mode
 if ($LASTEXITCODE -ne 0) { throw "Updater berhenti (exit $LASTEXITCODE). Baca pesan di atas; jangan paksa menimpa file." }
} finally {
 Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
}
